// Shared, deterministic XP presentation. XP is read from the protected ledger
// only; no points can be generated by browser actions or course-preview access.
export const XP_PER_STAGE=100;
export function xpThreshold(level){
 if(!Number.isSafeInteger(level)||level<1)throw new Error('Invalid learning level');
 return XP_PER_STAGE*(level-1)*level/2;
}
export function levelFromXp(value){
 const total=Number.isSafeInteger(value)&&value>=0?value:0;
 let level=1;
 while(level<1000&&total>=xpThreshold(level+1))level++;
 const start=xpThreshold(level),next=xpThreshold(level+1);
 return {total,level,currentLevelStart:start,nextLevelAt:next,
  intoLevel:total-start,neededToNext:next-total,
  percent:Math.min(100,Math.max(0,Math.floor((total-start)/(next-start)*100)))};
}
export function xpSummary(credits=[]){
 const seen=new Set();
 const byCourse={musnad:0,arud:0};
 for(const credit of credits){
  if(!credit||!Object.hasOwn(byCourse,credit.course_slug)||!Number.isInteger(credit.stage_index)||credit.stage_index<0||credit.stage_index>11||credit.xp_amount!==XP_PER_STAGE)continue;
  const key=credit.course_slug+':'+credit.stage_index;
  if(seen.has(key))continue;
  seen.add(key);
  byCourse[credit.course_slug]+=XP_PER_STAGE;
 }
 return {...levelFromXp(Object.values(byCourse).reduce((sum,n)=>sum+n,0)),byCourse};
}
